            if (dp[j] === 0) continue;
            for (let c = 0; c < 2; c++) {
                let nextJ = trans[j][c];
                nextDp[nextJ] += dp[j];
            }
        }
        dp = nextDp;
    }

    // Total strings without s as substring in any rotation
    let total = Math.pow(2, n);
    let without = 0;
    for (let j = 0; j < m; j++) {
        without += dp[j];
    }

    console.log(total - without);
}

function buildFail(s) {
    const m = s.length;
    const fail = new Array(m).fill(0);
    for (let i = 1; i < m; i++) {
        let j = fail[i - 1];
        while (j > 0 && s[i] !== s[j]) {
            j = fail[j - 1];
        }
        if (s[i] === s[j]) j++;
        fail[i] = j;
    }
    return fail;
}

function buildTransition(s, fail) {
    const m = s.length;
    const trans = new Array(m + 1);
    for (let j = 0; j <= m; j++) {
        trans[j] = new Array(2);
        for (let c = 0; c < 2; c++) {
