const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, output: process.stdout });

function readInput() {
    return new Promise((resolve) => {
        let n, s;
        rl.on('line', (line) => {
            if (n === undefined) n = parseInt(line);
            else s = line.trim();
        }).on('close', () => resolve({ n, s }));
    });
}

function computeLPS(pattern) {
    const lps = new Array(pattern.length).fill(0);
    let len = 0;
    let i = 1;
    while (i < pattern.length) {
        if (pattern[i] === pattern[len]) {
            len++;
            lps[i] = len;
            i++;
        } else {
            if (len !== 0) {
                len = lps[len - 1];
            } else {
                lps[i] = 0;
                i++;
            }
        }
    }
    return lps;
}

function buildTransitionFunction(pattern) {
    const m = pattern.length;
    const lps = computeLPS(pattern);
    const trans = Array.from({ length: m + 1 }, () => new Array(2).fill(0));
    for (let state = 0; state <= m; state++) {
        for (let c = 0; c < 2; c++) {
            if (state < m && pattern[state] === '0'.charCodeAt(0) + c) {
                trans[state][c] = state + 1;
            } else if (state === 0) {
                trans[state][c] = 0;
            } else {
                trans[state][c] = trans[lps[state - 1]][c];
            }
        }
    }
    return trans;
}

function solve(n, s) {
    const m = s.length;
    if (m > n) return 0;
    const trans = buildTransitionFunction(s);
