function main() {
    const n = parseInt(input[0]);
    const s = input[1];
    const m = s.length;

    if (m > n) {
        console.log(0);
        return;
    }

    // Precompute the failure function (partial match table) for KMP
    const fail = new Array(m).fill(0);
    for (let i = 1, j = 0; i < m; ++i) {
        while (j > 0 && s[i] !== s[j]) j = fail[j - 1];
        if (s[i] === s[j]) ++j;
        fail[i] = j;
    }

    // DP state: [position, kmp_state]
    // dp[pos][kmp_state] = number of ways
    let dp = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
    dp[0][0] = 1;

    for (let pos = 0; pos < n; ++pos) {
        for (let state = 0; state < m; ++state) {
            if (dp[pos][state] === 0) continue;
            for (const c of ['0', '1']) {
                let nextState = state;
                while (nextState > 0 && c !== s[nextState]) nextState = fail[nextState - 1];
                if (c === s[nextState]) ++nextState;
                if (nextState < m) {
                    dp[pos + 1][nextState] += dp[pos][state];
                }
            }
        }
    }

    // Sum all dp[n][state] where state < m (i.e., s was never fully matched)
    let total = 0;
    for (let state = 0; state < m; ++state) {
        total += dp[n][state];
    }

    // Total binary strings of length n minus those that never contain s
    const result = Math.pow(2, n) - total;
    console.log(result);
